    let policy_base = items_premium(items)?;
    let mut total = policy_base;

    if customer.years_with_mhpco >= LOYALTY_YEARS {
        total = total - policy_base.percent(LOYALTY_DISCOUNT);
    }
    // Every item in a quote counts as a first insurance, regardless of history.
    total = total + policy_base.percent(FIRST_INSURANCE_SURCHARGE);
    if customer.has_previous_contract {
        total = total - policy_base.percent(FOLLOW_UP_DISCOUNT);
    }

    Ok((total + Amount::whole(PROCESSING_FEE)).round_up())
}

